    assert(target(1.0) == 20.5);
}

class Parent:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return "parent:" + self.name


class Child(Parent):
    def __init__(self, name, level):
        super().__init__(name)
        self.level = level

    def describe(self):
        return super().describe() + ":level=" + str(self.level)


class Base:
    def steps(self):
        return ["Base"]


class Left(Base):
    def steps(self):
        return ["Left"] + super().steps()


class Right(Base):
    def steps(self):
        return ["Right"] + super().steps()


class Combined(Left, Right):
    def steps(self):
        return ["Combined"] + super().steps()


def main():
    child = Child("task", 2)
    assert isinstance(child, Parent)
    assert child.describe() == "parent:task:level=2"
    assert Combined().steps() == ["Combined", "Left", "Right", "Base"]
    assert Combined.__mro__ == (Combined, Left, Right, Base, object)
    print(child.describe())
    print(" -> ".join(Combined().steps()))
    print(" -> ".join(cls.__name__ for cls in Combined.__mro__))


if __name__ == "__main__":
    main()

public final class InheritanceDemo {
    interface Named {
        String describe();
    }

    static class Parent implements Named {
        protected final String name;

        Parent(String name) {
            this.name = name;
        }

        @Override
        public String describe() {
            return "parent:" + name;
        }
    }

    static final class Child extends Parent {
        private final int level;

        Child(String name, int level) {
            super(name);
            this.level = level;
        }

        @Override
        public String describe() {
            return super.describe() + ":level=" + level;
        }
    }

    public static void main(String[] args) {
        Parent parent = new Child("task", 2);
        Named named = parent;
        if (!"parent:task:level=2".equals(named.describe())) {
            throw new AssertionError("dynamic dispatch failed");
        }
        System.out.println(named.describe());
    }
}

"""Minimal metadata/registration example, not an ORM or database adapter."""
class Field:
    def __init__(self, column):
        self.column = column

class ModelMeta(type):
    registry = {}

    def __new__(mcls, name, bases, namespace, **kwargs):
        fields = {}
        for base in reversed(bases):
            fields.update(getattr(base, '__fields__', {}))
        fields.update({key: value for key, value in namespace.items()
                       if isinstance(value, Field)})
        namespace['__fields__'] = fields
        # Pass the original namespace, including any __classcell__, to type.
        cls = super().__new__(mcls, name, bases, namespace, **kwargs)
        if not namespace.get('__abstract__', False):
            mcls.registry[name] = cls
        return cls

class Model(metaclass=ModelMeta):
    __abstract__ = True
    id = Field('id')

    def label(self):
        return 'model'

class User(Model):
    name = Field('user_name')

    def label(self):
        return super().label() + ':user'

# One-argument type inspects a type; three-argument type creates a class.
Point = type('Point', (object,), {'unit': 'm', '__module__': __name__})
assert type(Point()) is Point
assert Point.unit == 'm'
assert type(User) is ModelMeta and isinstance(User(), Model)
assert ModelMeta.registry['User'] is User and 'Model' not in ModelMeta.registry
assert set(User.__fields__) == {'id', 'name'}
assert User.__fields__['name'].column == 'user_name'
assert set(Model.__fields__) == {'id'}  # child metadata does not mutate parent
assert User().label() == 'model:user'  # __classcell__ preserved
print('PASS: dynamic type, metaclass identity, inherited metadata, registry, super')

