};
inline int square(int x) { return x * x; } // demonstration uses small values

// C-style ellipsis: caller contract is exactly count arguments of promoted type int.
int sum_ints(std::size_t count, ...) {
    va_list args;
    va_start(args, count);
    int sum = 0;
    for (std::size_t i = 0; i < count; ++i) sum += va_arg(args, int);
    va_end(args);
    return sum; // caller must also ensure the sum fits in int
}
template<class T, class... Args>
std::unique_ptr<T> make_owned(Args&&... args) {
    return std::unique_ptr<T>(new T(std::forward<Args>(args)...));
}
const char* category(int&) { return "lvalue"; }
const char* category(const int&) { return "const lvalue"; }
const char* category(int&&) { return "rvalue"; }
template<class T> const char* forwarded(T&& value) {
    return category(std::forward<T>(value));
}

// Deliberate ownership contract: value_ is an ordinary int;
// p_ uniquely owns zero or one independently allocated int, never an array.
class Owner {
    int value_;
    int* p_;
public:
    explicit Owner(int value = 0) noexcept : value_(value), p_(nullptr) {}
    Owner(int value, int payload) : value_(value), p_(new int(payload)) {}
    ~Owner() { delete p_; }
    Owner(const Owner& other)
        : value_(other.value_), p_(other.p_ ? new int(*other.p_) : nullptr) {}
    Owner& operator=(const Owner& other) {
        if (this == &other) return *this;
        // Allocate/copy before changing *this: allocation failure leaves it intact.
        int* next = other.p_ ? new int(*other.p_) : nullptr;
        delete p_;
        p_ = next;
        value_ = other.value_;
        return *this;
    }
    Owner(Owner&& other) noexcept
        : value_(other.value_), p_(std::exchange(other.p_, nullptr)) {}
    Owner& operator=(Owner&& other) noexcept {
        if (this != &other) {
            delete p_;
            value_ = other.value_;
            p_ = std::exchange(other.p_, nullptr);
        }
        return *this;
    }
    int value() const noexcept { return value_; }
    const int* payload() const noexcept { return p_; }
    void set_payload(int value) { assert(p_); *p_ = value; }
};

struct NoCopyMove {
    int value;
    explicit NoCopyMove(int x) : value(x) {}
    NoCopyMove(const NoCopyMove&) = delete;
    NoCopyMove(NoCopyMove&&) = delete;
};
NoCopyMove guaranteed_elision() { return NoCopyMove(9); } // C++17 prvalue
struct Counted {
    static int copies, moves;
    Counted() = default;
    Counted(const Counted&) { ++copies; }
    Counted(Counted&&) noexcept { ++moves; }
};
int Counted::copies = 0;
int Counted::moves = 0;
Counted named_return() { Counted value; return value; } // NRVO optional

int main() {
    int external = 2;
    Initialized obj(external);
    assert(obj.first == 7 && obj.second == 8);
    obj.ref = 4;
    assert(external == 4);
    assert(square(3) == 9 && sum_ints(3, 1, 2, 3) == 6);
    auto text = make_owned<std::string>(3, 'x');
    assert(*text == "xxx");
    int n = 5; const int cn = 6;
    assert(std::string(forwarded(n)) == "lvalue");
    assert(std::string(forwarded(cn)) == "const lvalue");
    assert(std::string(forwarded(7)) == "rvalue");
    int&& named_rvalue_reference = 8;
    assert(std::string(category(named_rvalue_reference)) == "lvalue");
    assert(std::string(forwarded(std::move(named_rvalue_reference))) == "rvalue");
    const int& lifetime_extended = 42;
    assert(lifetime_extended == 42);
    using L = int&; using R = int&&;
    static_assert(std::is_same_v<L&, int&> && std::is_same_v<L&&, int&>);
    static_assert(std::is_same_v<R&, int&> && std::is_same_v<R&&, int&&>);
    Owner a(1, 10), b(2, 20), empty;
    Owner copied(a);
    assert(copied.payload() != a.payload() && *copied.payload() == 10);
    b = a;
    assert(b.value() == 1 && b.payload() != a.payload());
    b.set_payload(30);
    assert(*a.payload() == 10 && *b.payload() == 30);
    a = a;
    assert(*a.payload() == 10);
    b = empty;
    assert(!b.payload() && b.value() == 0);
    (b = copied) = a;
    assert(b.value() == 1 && *b.payload() == 10);
    Owner moved(std::move(b));
    assert(!b.payload() && *moved.payload() == 10);
    empty = std::move(moved);
    assert(!moved.payload() && *empty.payload() == 10);
    empty = std::move(empty);
    assert(*empty.payload() == 10);
    auto no_copy = guaranteed_elision();
    assert(no_copy.value == 9);
    auto nrvo = named_return(); (void)nrvo;
    std::cout << "PASS value/ownership/forwarding; optional NRVO observations copies="
              << Counted::copies << " moves=" << Counted::moves << '\n';
}

#include <assert.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Base Base;
typedef struct Ops {
    int (*value)(const Base *self);
    void (*destroy)(Base *self);
} Ops;
struct Base { const Ops *ops; int common; };
typedef struct Derived { Base base; int extra; } Derived;
_Static_assert(offsetof(Derived, base) == 0, "base is the first member");
static unsigned destroyed;

static int derived_value(const Base *self) {
    /* This callback is installed only for a live Derived's first Base member. */
    const Derived *d = (const Derived *)self;
    return d->base.common > d->extra ? d->base.common : d->extra;
}
static void derived_destroy(Base *self) {
    Derived *d = (Derived *)self;
    ++destroyed;
    free(d);
}
static const Ops derived_ops = {derived_value, derived_destroy};
static Base *derived_new(int common, int extra) {
    Derived *d = malloc(sizeof *d);
    if (!d) return NULL;
    d->base.ops = &derived_ops;
    d->base.common = common;
    d->extra = extra;
    return &d->base;
}
static int base_value(const Base *self) {
    assert(self && self->ops && self->ops->value);
    return self->ops->value(self);
}
static void base_destroy(Base *self) {
    if (self) { assert(self->ops && self->ops->destroy); self->ops->destroy(self); }
}
int main(void) {
    Base *b = derived_new(3, 4);
    if (!b) return 1;
    assert(base_value(b) == 4);
    b->common = 10;
    assert(base_value(b) == 10);
    base_destroy(b); b = NULL;
    assert(destroyed == 1);
    base_destroy(b);
    assert(destroyed == 1);
    puts("PASS C11 embedded-base dispatch and destruction");
    return 0;
}

#include <array>
#include <atomic>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <thread>
// Exactly one producer and one consumer. No close, blocking, or MPMC API.
template<std::size_t Capacity> class SpscRing {
    static_assert(Capacity > 0 && Capacity < 1000000);
    static_assert(std::atomic<std::size_t>::is_always_lock_free,
                  "This example requires lock-free atomic indices");
    std::array<int, Capacity + 1> data_{};
    std::atomic<std::size_t> head_{0}, tail_{0};
    static std::size_t next(std::size_t i) { return (i + 1) % (Capacity + 1); }
public:
    bool try_push(int value) {
        const auto tail = tail_.load(std::memory_order_relaxed);
        const auto n = next(tail);
        if (n == head_.load(std::memory_order_acquire)) return false;
        data_[tail] = value;
        tail_.store(n, std::memory_order_release);
        return true;
    }
    bool try_pop(int& value) {
        const auto head = head_.load(std::memory_order_relaxed);
        if (head == tail_.load(std::memory_order_acquire)) return false;
        value = data_[head];
        head_.store(next(head), std::memory_order_release);
        return true;
    }
};
template<std::size_t N> std::size_t test() {
    std::size_t checks=0;
    for (int trial=0;trial<10;++trial) {
        SpscRing<N> q; int value=-1;
        assert(!q.try_pop(value) && value==-1);++checks;
        for (std::size_t i=0;i<N;++i) { assert(q.try_push(static_cast<int>(i)));++checks; }
        assert(!q.try_push(-100));++checks;
        for (std::size_t i=0;i<N;++i) { assert(q.try_pop(value) && value==static_cast<int>(i));++checks; }
        assert(!q.try_pop(value));++checks;
        constexpr int count=5000;
        std::atomic<bool> start{false};
        std::thread producer([&]{
            while(!start.load(std::memory_order_acquire)) std::this_thread::yield();
            for(int i=0;i<count;++i) while(!q.try_push(i)) std::this_thread::yield();
        });
        std::thread consumer([&]{
            while(!start.load(std::memory_order_acquire)) std::this_thread::yield();
            for(int i=0;i<count;++i) {
                int got;
                while(!q.try_pop(got)) std::this_thread::yield();
                assert(got==i);++checks; // Only this thread changes checks until join.
            }
        });
        start.store(true,std::memory_order_release);
        producer.join();consumer.join();assert(!q.try_pop(value));++checks;
    }
    return checks;
}
int main() {
    const auto checks=test<1>()+test<2>()+test<17>();
    std::cout<<"PASS SPSC capacities 1/2/17, 30 pairs, 150000 ordered values, "<<checks<<" checks\n";
}

